// A IA erra. Antes de devolver, confere o que nao pode mudar: numero, link e
// tamanho. Falhou a conferencia, devolve o texto ORIGINAL - melhor sem
// variacao do que com um preco trocado indo para centenas de pessoas.
const original = String($('Variar mensagem').first().json.body.message || '');
let saida = '';
try {
  const r = $input.first().json;
  saida = String((((r.choices || [])[0] || {}).message || {}).content || r.content || '').trim();
} catch (e) { saida = ''; }

// tira aspas e cercas que o modelo as vezes adiciona
saida = saida.replace(/^```[a-z]*\s*/i, '').replace(/```$/, '').trim();
if (saida.length > 1 && saida[0] === '"' && saida[saida.length - 1] === '"') saida = saida.slice(1, -1).trim();

function numeros(s){ return (String(s).match(/\d[\d.,]*/g) || []).map(function(x){ return x.replace(/[.,]$/,''); }).sort(); }
function links(s){ return (String(s).match(/https?:\/\/\S+/gi) || []).sort(); }
// resolve as variacoes para medir o texto como ele vai chegar
function umaVersao(s){
  let t = String(s);
  for (let i = 0; i < 10; i++) {
    const a = t;
    t = t.replace(/\{([^{}]*\|[^{}]*)\}/g, function(_, d){ return d.split('|')[0]; });
    if (t === a) break;
  }
  return t.replace(/\{\{\s*nome\s*\}\}/gi, '');
}

const motivos = [];
if (!saida) motivos.push('a IA nao respondeu');
if (saida && saida.indexOf('|') < 0) motivos.push('nenhuma variacao foi criada');
if (saida) {
  const amostra = umaVersao(saida);
  if (JSON.stringify(numeros(amostra)) !== JSON.stringify(numeros(original))) motivos.push('mexeu em algum numero');
  if (JSON.stringify(links(amostra)) !== JSON.stringify(links(original))) motivos.push('mexeu em algum link');
  if (amostra.length > original.length * 1.6) motivos.push('ficou longa demais');
}

const ok = motivos.length === 0;
return [{ json: {
  ok: true,
  variou: ok,
  message: ok ? saida : original,
  aviso: ok ? null : ('Mantive a mensagem original: ' + motivos.join('; ') + '.')
} }];
